<script setup lang="ts">
import { computed, ref } from 'vue';
const props=defineProps<{values?:{date:string;qty:number}[]; ocean?:boolean; replay?:number; error?:boolean}>();
const hovered=ref(-1);
const points=computed(()=>{const a=props.values||[];const max=Math.max(1,...a.map(v=>v.qty));return a.map((v,i)=>({x:4+i/Math.max(1,a.length-1)*150,y:36-v.qty/max*30,...v}));});
const line=computed(()=>points.value.map((v,i)=>`${i?'L':'M'} ${v.x} ${v.y}`).join(' '));
const area=computed(()=>line.value?`${line.value} L 154 40 L 4 40 Z`:'');
const active=computed(()=>points.value[hovered.value]);
function hover(e:MouseEvent){const rect=e.currentTarget instanceof Element?e.currentTarget.getBoundingClientRect():null;if(rect)hovered.value=Math.max(0,Math.min(points.value.length-1,Math.round((e.clientX-rect.left)/rect.width*(points.value.length-1))));}
</script>
<template><div class="sales-trend" :class="{ocean}" @mouseleave="hovered=-1"><template v-if="points.length"><svg :key="replay" viewBox="0 0 158 44" role="img" :aria-label="`近${points.length}天销量走势，合计${values?.reduce((s,v)=>s+v.qty,0)}件`" @mousemove="hover"><title>{{values?.map(v=>`${v.date}: ${v.qty}件`).join('；')}}</title><line x1="4" y1="39" x2="154" y2="39" stroke="#edf0f5"/><g class="trend-reveal"><path :d="area" fill="currentColor" opacity=".06"/><path :d="line" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></g><template v-if="active"><line :x1="active.x" :x2="active.x" y1="3" y2="40" stroke="currentColor" opacity=".25" stroke-dasharray="2 2"/><circle :cx="active.x" :cy="active.y" r="2.5" fill="currentColor"/></template></svg><div v-if="active" class="trend-tooltip">{{active.date.slice(5)}} · {{active.qty}} 件</div></template><span v-else class="trend-empty">{{error?'走势加载失败':'暂无销量走势'}}</span></div></template>
<style scoped>.sales-trend{position:relative;width:158px;color:#45a389;height:44px}.sales-trend.ocean{color:#2670d7}.sales-trend svg{width:158px;height:44px;display:block;overflow:visible}.trend-reveal{clip-path:inset(0 0 0 0);animation:reveal 1.2s cubic-bezier(.2,.65,.3,1) both}.sales-trend:hover .trend-reveal{animation:reveal-hover .8s ease both}.trend-tooltip{position:absolute;left:15px;top:-17px;background:#283447;color:white;padding:3px 7px;border-radius:4px;font-size:10px;pointer-events:none;z-index:3}.trend-empty{font-size:11px;color:#a8b0bd;line-height:44px}@keyframes reveal{from{clip-path:inset(0 100% 0 0)}to{clip-path:inset(0 0 0 0)}}@keyframes reveal-hover{from{clip-path:inset(0 100% 0 0)}to{clip-path:inset(0 0 0 0)}}@media(prefers-reduced-motion:reduce){.trend-reveal,.sales-trend:hover .trend-reveal{animation:none}}</style>
